//#CTL2
function string regexQuote(string s) {
    string meta = ".^$*+?()[]{}|\\";
    string out = "";
    integer i;
    for (i = 0; i < length(s); i++) {
        string ch = substring(s, i, i + 1);
        if (indexOf(meta, ch) >= 0) out = out + "\\" + ch;
        else out = out + ch;
    }
    return out;
}

function integer transform() {
    $out.0.out = replace($in.0.s, regexQuote("."), "_");
    return ALL;
}
```

